package org.apache.parquet.crypto.keytools;

import static org.junit.jupiter.api.Assertions.assertThrows;

import org.apache.hadoop.conf.Configuration;
import org.apache.hadoop.fs.Path;
import org.apache.parquet.hadoop.api.WriteSupport.WriteContext;
import org.junit.jupiter.api.Test;

class PropertiesDrivenCryptoFactoryGetFileEncryptionPropertiesTests {

  @Test
  void rejectsNullWriteContextEvenWhenEncryptionIsNotConfigured() {
    PropertiesDrivenCryptoFactory factory = new PropertiesDrivenCryptoFactory();
    Configuration configuration = new Configuration(false);
    Path outputPath = new Path("file:///tmp/output.parquet");

    assertThrows(
        RuntimeException.class,
        () -> factory.getFileEncryptionProperties(configuration, outputPath, null));
  }
}
